// ListReports runs the :many query against mysql.
func (q *mysqlQueries) ListReports(ctx context.Context, db DBTX, arg ListReportsParams) ([]ListReportsRow, error) {
	rows, err := db.QueryContext(ctx, q.listReports,
		arg.CreatedAfter,
		arg.CreatedBefore,
		arg.UpdatedAfter,
		arg.UpdatedBefore,
		arg.IncludeArchived,
		arg.Scope,
		arg.IncludeArchived,
		arg.Scope,
		arg.CreatedAfter,
		arg.CreatedBefore,
		arg.UpdatedAfter,
		arg.UpdatedBefore,
		arg.IncludeArchived,
		arg.Scope,
		arg.PageCursor,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []ListReportsRow

	for rows.Next() {
		var i ListReportsRow

		if err := rows.Scan(
			&i.ID,
			&i.Scope,
			&i.Reporter,
			&i.Kind,
			&i.Details,
			&i.SubjectType,
			&i.SubjectID,
			&i.Status,
			&i.Resolution,
			&i.ClosedAt,
			&i.CreatedAt,
			&i.LastUpdatedAt,
			&i.ArchivedAt,
			&i.FilteredCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

